import * as THREE from 'three/webgpu';
import { color, mix, uv } from 'three/tsl';
import gsap from 'gsap';

const ENTRIES = [
  { label: 'HOME', id: 'home' },
  { label: 'FEATURES', id: 'features' },
  { label: 'COLLECTION', id: 'collection' },
  { label: 'PRICING', id: 'pricing' },
  { label: 'JOURNAL', id: 'journal' }
];

const C = {
  RAIL_WIDTH: 3.6,
  RAIL_HEIGHT: 0.5,
  ENTRY_SPACING: 0.68,
  ENTRY_WIDTH: 0.6,
  ENTRY_HEIGHT: 0.34,
  UNDERLINE_WIDTH: 0.28,
  UNDERLINE_HEIGHT: 0.025,
  UNDERLINE_OFFSET_Y: -0.06,
  SHADOW_OFFSET_Y: -0.06
};

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.y = 0.4;

  let activeIndex = 0;
  const state = { animations: [], geometries: [], materials: [], entryGroups: [], textMeshes: [] };

  // Shadow plane
  const shadowGeom = new THREE.PlaneGeometry(C.RAIL_WIDTH + 0.2, 0.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
    renderOrder: -2
  });
  const shadowPlane = new THREE.Mesh(shadowGeom, shadowMat);
  shadowPlane.position.y = C.SHADOW_OFFSET_Y;
  root.add(shadowPlane);
  state.geometries.push(shadowGeom);
  state.materials.push(shadowMat);

  // Rail with gradient metallic material
  const railGeom = new THREE.PlaneGeometry(C.RAIL_WIDTH, C.RAIL_HEIGHT);
  const railMat = new THREE.MeshStandardMaterial({
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2
  });
  railMat.colorNode = mix(color(0x101015), color(0x1b1b23), uv.y.mul(0.5).add(0.5));
  const railPlane = new THREE.Mesh(railGeom, railMat);
  railPlane.position.z = 0.15;
  root.add(railPlane);
  state.geometries.push(railGeom);
  state.materials.push(railMat);

  // Entries container
  const entriesGroup = new THREE.Group();
  root.add(entriesGroup);

  // Underline bar
  const underlineBar = new THREE.Group();
  root.add(underlineBar);

  const underlineGeom = new THREE.PlaneGeometry(C.UNDERLINE_WIDTH, C.UNDERLINE_HEIGHT);
  const underlineMat = new THREE.MeshBasicMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    transparent: true,
    renderOrder: 1
  });
  const underlineMesh = new THREE.Mesh(underlineGeom, underlineMat);
  underlineMesh.position.y = C.UNDERLINE_OFFSET_Y;
  underlineMesh.position.z = 0.17;
  underlineBar.add(underlineMesh);
  state.geometries.push(underlineGeom);
  state.materials.push(underlineMat);

  // Create entries
  ENTRIES.forEach((entry, idx) => {
    const xPos = (idx - 2) * C.ENTRY_SPACING;
    const isActive = idx === activeIndex;

    const entryGroup = new THREE.Group();
    entryGroup.position.x = xPos;
    entryGroup.position.z = 0.16;
    entriesGroup.add(entryGroup);
    state.entryGroups.push({ group: entryGroup, index: idx });

    // Hit area
    const hitGeom = new THREE.PlaneGeometry(C.ENTRY_WIDTH, C.ENTRY_HEIGHT);
    const hitMat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0,
      depthTest: false
    });
    const hitPlane = new THREE.Mesh(hitGeom, hitMat);
    entryGroup.add(hitPlane);
    state.geometries.push(hitGeom);
    state.materials.push(hitMat);

    // Text mesh from fontAtlas
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: entry.label,
      font: 'JetBrains Mono',
      size: 0.13,
      weight: isActive ? 700 : 400,
      letterSpacing: 0.08,
      align: 'center'
    });
    textMesh.position.z = 0.01;
    if (textMesh.material) {
      textMesh.material.color.setHex(isActive ? 0xe8ecf2 : 0xa6adba);
    }
    entryGroup.add(textMesh);
    state.textMeshes.push({ mesh: textMesh, index: idx });

    // Event handlers
    hitPlane.userData.handlers = {
      onPointerOver: () => {
        if (idx !== activeIndex && textMesh.material) {
          state.animations.push(gsap.to(textMesh.material.color, {
            r: 0xe8 / 255,
            g: 0xec / 255,
            b: 0xf2 / 255,
            duration: 0.16,
            ease: 'power2.inOut'
          }));
        }
      },
      onPointerOut: () => {
        if (idx !== activeIndex && textMesh.material) {
          state.animations.push(gsap.to(textMesh.material.color, {
            r: 0xa6 / 255,
            g: 0xad / 255,
            b: 0xba / 255,
            duration: 0.16,
            ease: 'power2.inOut'
          }));
        }
      },
      onPointerDown: () => {
        state.animations.push(gsap.to(entryGroup.scale, {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.out'
        }));
        state.animations.push(gsap.to(entryGroup.position, {
          z: 0.13,
          duration: 0.12,
          ease: 'back.out'
        }));
      },
      onPointerUp: () => {
        state.animations.push(gsap.to(entryGroup.scale, {
          x: 1,
          y: 1,
          duration: 0.12,
          ease: 'back.out'
        }));
        state.animations.push(gsap.to(entryGroup.position, {
          z: 0.16,
          duration: 0.12,
          ease: 'back.out'
        }));

        if (idx !== activeIndex) {
          activeIndex = idx;

          state.textMeshes.forEach(({ mesh, index: midx }) => {
            if (mesh.material) {
              state.animations.push(gsap.to(mesh.material.color, {
                r: (midx === idx ? 0xe8 : 0xa6) / 255,
                g: (midx === idx ? 0xec : 0xad) / 255,
                b: (midx === idx ? 0xf2 : 0xba) / 255,
                duration: 0.16,
                ease: 'power2.inOut'
              }));
            }
          });

          state.animations.push(gsap.to(underlineBar.position, {
            x: xPos,
            duration: 0.26,
            ease: 'power4.out'
          }));
        }
      }
    };
  });

  // Mount animation
  state.animations.push(gsap.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out'
  }));

  root.userData.cleanup = () => {
    state.animations.forEach(t => t.kill());
    state.geometries.forEach(g => g.dispose());
    state.materials.forEach(m => m.dispose());
    state.textMeshes.forEach(({ mesh }) => {
      if (mesh.geometry) mesh.geometry.dispose();
      if (mesh.material) mesh.material.dispose();
    });
  };

  return root;
}
